                                        619,
                                        135
                                    ],
                                    "spans": [
                                        {
                                            "bbox": [
                                                6,
                                                90,
                                                619,
                                                135
                                            ],
                                            "type": "text",
                                            "content": "(二)砌筑工程高度在1.35~3.60m者按里脚手架计算，高度在3.60m以上者按外脚手架计算。独立混凝土柱按设计图示尺寸以结构外围周长另加3.60m乘以高度按单排脚手架计算。独立砖柱高度在3.60m以内者，按柱外围周长乘实砌高度按里脚手架计算；高度3.60m以上按柱外围加3.60m乘实砌高度按单排脚手架计算。"
                                        }
                                    ]
                                }
                            ],
                            "index": 4,
                            "merge_prev": false
                        },
                        {
                            "bbox": [
                                6,
                                137,
                                619,
